import React, { useEffect } from 'react';
import { Link } from 'react-router-dom';
import { motion, useAnimation } from 'framer-motion';
import { useInView } from 'react-intersection-observer';
import styles from './HomePage.module.css';

const FadeInSection = ({ children, className }) => {
  const controls = useAnimation();
  const [ref, inView] = useInView({ triggerOnce: true, threshold: 0.2 });

  useEffect(() => {
    if (inView) {
      controls.start('visible');
    }
  }, [controls, inView]);

  return (
    <motion.div
      ref={ref}
      className={className}
      initial="hidden"
      animate={controls}
      variants={{
        hidden: { opacity: 0, y: 50 },
        visible: { opacity: 1, y: 0, transition: { duration: 0.8, ease: 'easeOut' } },
      }}
    >
      {children}
    </motion.div>
  );
};

const HomePage = () => {
  return (
    <div className={styles.page}>
      {/* Геройская секция (уже была) */}
      <section className={styles.hero}>
        <div className={styles.heroContent}>
          <motion.h1 initial={{ y: -30, opacity: 0 }} animate={{ y: 0, opacity: 1 }} transition={{ duration: 0.8 }}>
            Искусство движения
          </motion.h1>
          <motion.p initial={{ y: 20, opacity: 0 }} animate={{ y: 0, opacity: 1 }} transition={{ delay: 0.3, duration: 0.8 }}>
            Эксклюзивные автомобили для тех, кто ценит совершенство
          </motion.p>
          <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} transition={{ delay: 0.6, duration: 0.5 }}>
            <Link to="/catalog" className={styles.cta}>Смотреть каталог</Link>
          </motion.div>
        </div>
        <div className={styles.heroOverlay} />
      </section>

      {/* Секция "Популярные модели" */}
      <FadeInSection className={styles.section}>
        <h2 className={styles.sectionTitle}>Популярные модели</h2>
        <div className={styles.cardGrid}>
          {popularCars.map((car, idx) => (
            <motion.div
              key={idx}
              className={styles.carCard}
              whileHover={{ scale: 1.05 }}
              transition={{ duration: 0.3 }}
            >
              <img src={car.image} alt={car.name} className={styles.cardImage} />
              <div className={styles.cardInfo}>
                <h3>{car.name}</h3>
                <p>от {car.price.toLocaleString()} ₽</p>
              </div>
            </motion.div>
          ))}
        </div>
      </FadeInSection>

      {/* Секция "Преимущества" */}
      <FadeInSection className={`${styles.section} ${styles.darkSection}`}>
        <h2 className={styles.sectionTitle}>Почему выбирают нас</h2>
        <div className={styles.benefitsGrid}>
          <div className={styles.benefit}>
            <span className={styles.benefitIcon}>🏆</span>
            <h4>Премиальный сервис</h4>
            <p>Индивидуальный подход к каждому клиенту</p>
          </div>
          <div className={styles.benefit}>
            <span className={styles.benefitIcon}>🚗</span>
            <h4>Лучшие бренды</h4>
            <p>Только официальные дилеры и гарантия</p>
          </div>
          <div className={styles.benefit}>
            <span className={styles.benefitIcon}>💰</span>
            <h4>Гибкие условия</h4>
            <p>Кредит и лизинг на выгодных условиях</p>
          </div>
        </div>
      </FadeInSection>

      {/* Секция "Как купить" */}
      <FadeInSection className={styles.section}>
        <h2 className={styles.sectionTitle}>Три шага к вашему автомобилю</h2>
        <div className={styles.steps}>
          <div className={styles.step}>
            <div className={styles.stepNumber}>1</div>
            <h4>Выберите автомобиль</h4>
            <p>Изучите каталог и найдите идеальную модель</p>
          </div>
          <div className={styles.step}>
            <div className={styles.stepNumber}>2</div>
            <h4>Рассчитайте условия</h4>
            <p>Воспользуйтесь кредитным калькулятором</p>
          </div>
          <div className={styles.step}>
            <div className={styles.stepNumber}>3</div>
            <h4>Оформите покупку</h4>
            <p>Мы подготовим все документы за 1 день</p>
          </div>
        </div>
      </FadeInSection>
    </div>
  );
};

// Данные для популярных моделей (временно, пока нет API избранного)
const popularCars = [
  { name: 'BMW M5', price: 14500000, image: 'https://images.unsplash.com/photo-1555215695-3004980ad54e?ixlib=rb-4.0.3&auto=format&fit=crop&w=600&q=80' },
  { name: 'Porsche 911', price: 22000000, image: 'https://images.unsplash.com/photo-1614162692292-7ac56d7f7f1e?ixlib=rb-4.0.3&auto=format&fit=crop&w=600&q=80' },
  { name: 'Range Rover Sport', price: 18500000, image: 'https://images.unsplash.com/photo-1606664515524-ed2f786a0bd6?ixlib=rb-4.0.3&auto=format&fit=crop&w=600&q=80' },
];

export default HomePage;
